    id: 'foundation-26', moduleId: 'module-6', title: 'Literary & Formal Tenses', subtitle: 'Understand written French and formal speech', order: 26, isCompleted: false, estimatedMinutes: 22, phases: ['learn', 'listen', 'read', 'speak', 'write'], pronunciationFocus: ['french-r', 'nasal-an', 'silent-letters'],
