    id: 'foundation-30', moduleId: 'module-6', title: 'Advanced Conversation Mastery', subtitle: 'Navigate any social or professional situation', order: 30, isCompleted: false, estimatedMinutes: 22, phases: ['learn', 'listen', 'read', 'speak', 'write'], pronunciationFocus: ['french-r', 'nasal-an', 'liaison'],
    speakingPrompts: ['Lead a mini-debate on a topic you care about', 'Give a 2-minute speech about something important to you', 'Practice interrupting politely, adding nuance, and summarizing'],
    writingTask: { prompt: 'Write a short structured speech (10 sentences) on a topic you care about, using advanced expressions from this lesson.', exampleResponse: "Permettez-moi de partager mon point de vue. Il me semble que la question est complexe. D'une part... D'autre part... En définitive, ce qui compte c'est..." },
    readingPassage: { title: 'L\'art de la conversation avancée', content: "À ce niveau, vous ne cherchez plus vos mots — vous choisissez les meilleurs. « Pour rebondir sur ce que vous avez dit » montre que vous écoutez activement. « Si je puis me permettre » est une interruption élégante. « Permettez-moi de nuancer » annonce que vous allez ajouter de la complexité. « Ce n'est pas tant X que Y qui me pose problème » est une formulation sophistiquée. « J'en viens au fait » recentre la discussion. « Cela dit » introduit une concession. La maîtrise de ces expressions transforme un bon français en un français élégant, celui qui impressionne les natifs.", comprehensionQuestions: [{ question: 'Que signifie « Si je puis me permettre » ?', answer: 'Une façon polie d\'interrompre', choices: ['Une demande d\'aide', 'Une façon polie d\'interrompre', 'Une question', 'Un refus'] }, { question: 'Que fait « J\'en viens au fait » ?', answer: 'Recentre la discussion', choices: ['Change de sujet', 'Recentre la discussion', 'Termine la conversation', 'Pose une question'] }] },
    listeningPrompt: { text: "Pour rebondir sur ce que vous avez dit, je pense qu'il y a un autre angle. Si je puis me permettre, il me semble que la question est mal posée. Ce n'est pas tant le budget que la stratégie qui pose problème. Permettez-moi de nuancer : certes le projet est ambitieux, mais cela dit, il est réalisable. En définitive, ce qui compte, c'est notre détermination.", comprehensionQuestions: [{ question: 'Quel est le vrai problème selon la personne ?', answer: 'La stratégie, pas le budget', choices: ['Le budget', 'La stratégie, pas le budget', 'Le temps', 'Les ressources humaines'] }, { question: 'Comment décrit-elle le projet ?', answer: 'Ambitieux mais réalisable', choices: ['Impossible', 'Facile', 'Ambitieux mais réalisable', 'Trop cher'] }] },
    items: [
      { id: 'f30-1', french: 'Pour rebondir sur ce que vous avez dit...', english: 'To build on what you said...', type: 'phrase', requiresPronunciationCheck: true },
      { id: 'f30-2', french: 'Si je puis me permettre...', english: 'If I may (very polite interjection)', type: 'phrase', requiresPronunciationCheck: true },
      { id: 'f30-3', french: 'Je me permets d\'intervenir', english: 'Allow me to interject', type: 'phrase', requiresPronunciationCheck: true },
      { id: 'f30-4', french: 'Pour résumer mon propos...', english: 'To summarize my point...', type: 'phrase', requiresPronunciationCheck: true },
      { id: 'f30-5', french: 'Il me semble que la question est mal posée', english: 'It seems to me the question is poorly framed', type: 'phrase', requiresPronunciationCheck: true },
      { id: 'f30-6', french: 'Permettez-moi de nuancer', english: 'Allow me to add nuance / qualify that', type: 'phrase', requiresPronunciationCheck: true },
      { id: 'f30-7', french: 'Ce n\'est pas tant X que Y qui me pose problème', english: 'It\'s not so much X as Y that concerns me', type: 'pattern', requiresPronunciationCheck: true },
      { id: 'f30-8', french: 'J\'en viens au fait', english: 'I\'ll get to the point', type: 'phrase', requiresPronunciationCheck: true },
      { id: 'f30-9', french: 'Cela dit / Ceci étant dit', english: 'That said / Having said that', type: 'connector', requiresPronunciationCheck: true },
      { id: 'f30-10', french: 'Loin de moi l\'idée de critiquer, mais...', english: 'Far be it from me to criticize, but...', type: 'phrase', requiresPronunciationCheck: true },
      { id: 'f30-11', french: 'En définitive, ce qui compte c\'est...', english: 'Ultimately, what matters is...', type: 'phrase', requiresPronunciationCheck: true },
      { id: 'f30-12', french: 'Je suis arrivé(e) au bout de mon raisonnement', english: 'I\'ve reached the end of my reasoning', type: 'phrase', requiresPronunciationCheck: true },
    ],
