    id: 'foundation-37', moduleId: 'module-8', title: 'Contemporary Slang & Verlan', subtitle: 'Understand real street French', order: 37, isCompleted: false, estimatedMinutes: 18, phases: ['learn', 'listen', 'read', 'speak', 'write'], pronunciationFocus: ['french-r', 'nasal-an'],
