    writingTask: { prompt: 'Rewrite these formal sentences in casual French using slang and contractions: 1. Je ne sais pas. 2. Il est bizarre. 3. Elle est ma petite amie.', exampleResponse: "1. Chais pas / J'sais pas. 2. Il est chelou / zarbi. 3. C'est ma meuf." },
    readingPassage: { title: 'Le verlan et l\'argot moderne', content: "Le verlan inverse les syllabes des mots : femme → meuf, mec → keum, bizarre → zarbi, louche → chelou, français → céfran. Certains mots de verlan sont entrés dans le dictionnaire ! L'argot évolue vite. Les jeunes disent « c'est chanmé » (méchant → chanmé = amazing), « un truc de ouf » (fou → ouf = crazy thing). « Kiffer » (aimer beaucoup) vient de l'arabe. « Wesh » (salut) aussi. Le français des banlieues mélange français, arabe, anglais et verlan. Comprendre cet argot est essentiel pour comprendre la culture populaire française.", comprehensionQuestions: [{ question: 'Comment forme-t-on le verlan ?', answer: 'En inversant les syllabes', choices: ['En ajoutant des syllabes', 'En inversant les syllabes', 'En enlevant des lettres', 'En changeant les voyelles'] }, { question: 'D\'où vient le mot « kiffer » ?', answer: 'De l\'arabe', choices: ['De l\'anglais', 'De l\'arabe', 'Du verlan', 'De l\'espagnol'] }] },
    listeningPrompt: { text: "Wesh, ça va ? T'es où là ? J'suis avec des meufs, on va en soirée. C'est chanmé comme endroit. Ramène-toi ! Y'a un truc de ouf ce soir. Allez, à toute !", comprehensionQuestions: [{ question: 'Que signifie « meufs » ?', answer: 'Femmes (verlan de femme)', choices: ['Hommes', 'Femmes (verlan de femme)', 'Amis', 'Enfants'] }, { question: 'Que veut dire « à toute » ?', answer: 'À tout à l\'heure (abrégé)', choices: ['À demain', 'À tout à l\'heure (abrégé)', 'Aurevoir', 'Bonne nuit'] }] },
