    id: 'foundation-38', moduleId: 'module-8', title: 'Regional French Variations', subtitle: 'Recognize Francophone diversity worldwide', order: 38, isCompleted: false, estimatedMinutes: 20, phases: ['learn', 'listen', 'read', 'speak', 'write'], pronunciationFocus: ['french-r', 'nasal-an', 'nasal-on'],
    speakingPrompts: ['Compare how to say the same thing in France, Quebec, and West Africa', 'Practice the Québécois accent by reading sentences aloud', 'Describe the francophone world: which countries speak French?'],
    writingTask: { prompt: 'Write a short paragraph describing the francophone world, mentioning at least 3 different French-speaking regions and how their French differs.', exampleResponse: "Le français est parlé sur cinq continents. Au Québec, on dit char pour voiture. En Belgique, on dit septante pour soixante-dix. En Côte d'Ivoire, le nouchi mélange français et langues locales." },
    readingPassage: { title: 'Le français dans le monde', content: "Le français est parlé sur cinq continents par 321 millions de personnes. Au Québec, on dit « char » pour voiture, « blonde » pour petite amie, et « dépanneur » pour petite épicerie. En Belgique, on dit « septante » (70) et « nonante » (90) au lieu de soixante-dix et quatre-vingt-dix. En Suisse, on dit « huitante » pour 80. En Afrique de l'Ouest, le français se mélange aux langues locales. Au Sénégal, on entend « Nanga def ? » (wolof pour « comment ça va ? ») dans la même conversation que du français. En Côte d'Ivoire, le « nouchi » est un argot unique. Chaque région enrichit le français.", comprehensionQuestions: [{ question: 'Combien de personnes parlent français dans le monde ?', answer: '321 millions', choices: ['100 millions', '200 millions', '321 millions', '500 millions'] }, { question: 'Comment dit-on 80 en Suisse ?', answer: 'Huitante', choices: ['Quatre-vingts', 'Huitante', 'Octante', 'Soixante-vingt'] }] },
