    speakingPrompts: ['Answer with y: Tu vas au cin\u00e9ma ? Oui, j\'y vais', 'Answer with en: Tu as des fr\u00e8res ? Oui, j\'en ai deux', 'Practice common expressions: On y va ! / J\'en ai marre'],
    writingTask: { prompt: 'Rewrite these sentences using y or en: 1. Je vais \u00e0 Paris. 2. J\'ai trois chats. 3. Je pense \u00e0 mon voyage. 4. Je veux du caf\u00e9.', exampleResponse: "1. J'y vais. 2. J'en ai trois. 3. J'y pense. 4. J'en veux." },
    readingPassage: { title: 'Y et en : petits mots, grande importance', content: "Y remplace \u00ab \u00e0 + lieu \u00bb ou \u00ab \u00e0 + chose \u00bb. Tu vas \u00e0 Paris ? J'y vais. Tu penses \u00e0 ton examen ? J'y pense. En remplace \u00ab de + nom \u00bb ou une quantit\u00e9. Tu as des enfants ? J'en ai deux. Tu veux du caf\u00e9 ? J'en veux. Attention \u00e0 ne pas confondre avec les personnes : pour les personnes, on utilise lui/leur (COI) et non y. Expressions courantes : On y va ! (Let's go!), J'en ai marre (I'm fed up), Il y en a beaucoup (There are many of them).", comprehensionQuestions: [{ question: 'Que remplace y ?', answer: '\u00e0 + lieu ou \u00e0 + chose', choices: ['de + nom', '\u00e0 + lieu ou \u00e0 + chose', 'une personne', 'un adjectif'] }, { question: 'Que signifie J\'en ai marre ?', answer: 'I\'m fed up', choices: ['I\'m happy', 'I\'m hungry', 'I\'m fed up', 'I\'m tired'] }] },
    listeningPrompt: { text: "Tu vas au march\u00e9 ? Oui, j'y vais ce matin. Tu veux des tomates ? J'en prends un kilo. Tu penses \u00e0 tes vacances ? J'y pense tout le temps ! Tu as de l'argent ? Non, je n'en ai plus. Allez, on y va !", comprehensionQuestions: [{ question: 'Combien de tomates prend-il ?', answer: 'Un kilo', choices: ['Deux kilos', 'Un kilo', 'Trois', 'Pas de tomates'] }, { question: 'A-t-il de l\'argent ?', answer: 'Non, il n\'en a plus', choices: ['Oui, beaucoup', 'Non, il n\'en a plus', 'Un peu', 'Il ne sait pas'] }] },
