    id: 'foundation-56', moduleId: 'module-8', title: 'Social Mastery & Cultural Fluency', subtitle: 'Navigate any social context with charm and ease', order: 56, isCompleted: false, estimatedMinutes: 22, phases: ['learn', 'listen', 'read', 'speak', 'write'], pronunciationFocus: ['french-r', 'nasal-an', 'liaison'],
